INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q389540', 'Battle of the Save', 'The Battle of Poetovio was fought in 388 between the forces of Western Roman Emperor Magnus Maximus and the Eastern Roman Emperor Theodosius I. Magnus Maximus''s army was defeated and he was later captured and executed at Aquileia.', 388, NULL, NULL, NULL, NULL, NULL, 'year', '388', 55, 'https://en.wikipedia.org/wiki/Battle_of_Poetovio'),
  ('Q836944', 'Battle of the Frigidus', 'The Battle of the Frigidus, also called the Battle of the Frigid River, was fought on 5 and 6 September 394 between the armies of the Roman emperor Theodosius the Great and the rebel augustus Eugenius (r. 392–394), in the eastern border of Roman Italy. Theodosius won the battle and defeated the usurpation of Eugenius and Arbogast, restoring unity to the Roman Empire.', 394, 9, 5, 394, 9, 6, 'day', '5 September 394 – 6 September 394', 68, 'https://en.wikipedia.org/wiki/Battle_of_the_Frigidus'),
  ('Q7510226', 'Siege of Marburg', 'The siege of Maribor was a siege of present-day Maribor, then known by its German name Marburg, in the Duchy of Styria within the Archduchy of Austria and the Holy Roman Empire. In the siege that happened during September 1532, a local garrison and citizens defended the fortified town of Maribor against the overwhelming force of the Ottoman Empire, led by their Sultan Suleiman the Magnificent and his Grand Vizier Pargalı Ibrahim Pasha.', 1532, 9, 21, 1532, 9, 21, 'day', '21 September 1532', 34, 'https://en.wikipedia.org/wiki/Siege_of_Maribor_(1532)'),
  ('Q681517', 'Battles of the Isonzo', 'The Battles of the Isonzo (also known as the Isonzo Front by historians, or the Soča Front; Slovene: soška fronta) were a series of eleven or twelve battles between the Austro-Hungarian and Italian armies in World War I mostly on the territory of present-day Slovenia, and the remainder in Italy along the Isonzo (Slovene: Soča) River on the eastern sector of the Italian Front between June 1915 and November 1917.', 1915, 5, 23, 1917, 10, 27, 'day', '23 May 1915 – 27 October 1917', 64, 'https://en.wikipedia.org/wiki/Battles_of_the_Isonzo'),
  ('Q674647', 'Marburg''s Bloody Sunday', 'Marburg''s Bloody Sunday (German: Marburger Blutsonntag, Slovene: Mariborska krvava nedelja) was a shooting that took place on Monday, 27 January 1919 in the city of Maribor (German: Marburg an der Drau) in Slovenia. Soldiers from the army of the Kingdom of Serbs, Croats and Slovenes (later Yugoslavia), under the command of Slovene officer Rudolf Maister, killed between 9 and 13 civilians of German ethnic origin, wounding a further 60, after the soldiers were attacked during a protest in the city centre.', 1919, 1, 27, NULL, NULL, NULL, 'day', '27 January 1919', 48, 'https://en.wikipedia.org/wiki/Marburg''s_Bloody_Sunday'),
  ('Q807324', 'Barbara Pit', 'The Barbara Pit massacre (Slovene: Pokol v Barbara rovu, Croatian: Pokolj u Barbarinom rovu), also known as the Huda Jama massacre, was the mass killing of prisoners of war of Ante Pavelić''s NDH Armed Forces and the Slovene Home Guard, as well as civilians, after the end of World War II in Yugoslavia in an abandoned coal mine near Huda Jama, Slovenia. More than a thousand prisoners of war and some civilians were executed by the Yugoslav Partisans during May and June 1945, following the Bleiburg repatriations by the British.', 1945, 6, 6, NULL, NULL, NULL, 'day', '6 June 1945', 45, 'https://en.wikipedia.org/wiki/Barbara_Pit_massacre'),
  ('Q4969273', 'Britannia Airways Flight 105', 'Britannia Airways Flight 105 (BY 105) was an international tourist chartered flight from London Luton Airport for a flight to Ljubljana Brnik Airport (today Ljubljana Jože Pučnik Airport). Passengers were primarily British, most of them going to their vacation in Yugoslavia.', 1966, 9, 1, NULL, NULL, NULL, 'day', '1 September 1966', 47, 'https://en.wikipedia.org/wiki/Britannia_Airways_Flight_105'),
  ('Q3562572', 'Inex-Adria Aviopromet Flight 1308', 'Inex-Adria Aviopromet Flight 1308 was a charter flight, operated with a McDonnell Douglas MD-82, which brought Yugoslav tourists to Corsica. On 1 December 1981, on its final approach, the plane crashed into Mont San Petru; all of the 180 passengers and crew died.', 1981, 12, 1, NULL, NULL, NULL, 'day', '1 December 1981', 55, 'https://en.wikipedia.org/wiki/Inex-Adria_Aviopromet_Flight_1308'),
  ('Q163883', 'Ten-Day War', 'The Ten-Day War (Slovene: Desetdnevna vojna), or the Slovenian War of Independence (Slovene: Slovenska osamosvojitvena vojna), was a brief armed conflict that followed Slovenia''s declaration of independence from Yugoslavia on 25 June 1991. It was fought between the Slovenian Territorial Defence and the Slovenian National Police Force on one side, and the Yugoslav People''s Army (JNA) on the other.', 1991, 6, 27, 1991, 7, 7, 'day', '27 June 1991 – 7 July 1991', 76, 'https://en.wikipedia.org/wiki/Ten-Day_War'),
  ('Q3296841', 'Slovenian border dispute agreement referendum', 'A referendum on resolving the border dispute with Croatia was held in Slovenia on 6 June 2010. Voters were asked whether the dispute should be brought before an international arbitration tribunal.', 2010, 6, 6, NULL, NULL, NULL, 'day', '6 June 2010', 37, 'https://en.wikipedia.org/wiki/2010_Slovenian_border_dispute_agreement_referendum'),
  ('Q4618383', '2010 Slovenia floods', 'The 2010 Slovenia floods, on the weekend of 17–19 September 2010, were caused by heavy rains in Slovenia, resulting in one of the worst floods in the country''s history. Among the regions affected were the capital Ljubljana, the Central Sava Valley, Laško, the Slovene Littoral and Lower Carniola.', 2010, 9, 19, NULL, NULL, NULL, 'day', '19 September 2010', 37, 'https://en.wikipedia.org/wiki/2010_Slovenia_floods'),
  ('Q7541810', 'Slovenian Family Code referendum, 2012', 'A referendum was held in Slovenia on 25 March 2012 on the new family code passed by the then-governing coalition led by Borut Pahor. The code was rejected with 54.55% of voters against the law.', 2012, 3, 25, NULL, NULL, NULL, 'day', '25 March 2012', 39, 'https://en.wikipedia.org/wiki/2012_Slovenian_Family_Code_referendum'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q21789612', 'Slovenian same-sex marriage referendum, 2015', 'A referendum on a bill legalising same-sex marriage was held in Slovenia on 20 December 2015. The bill was rejected, as a majority of voters voted against and the votes against were more than 20% of registered voters.', 2015, 12, 20, NULL, NULL, NULL, 'day', '20 December 2015', 48, 'https://en.wikipedia.org/wiki/2015_Slovenian_same-sex_marriage_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107226133', '2021 Slovenian Waters Act referendum', 'A referendum on amendments to the Waters Act was held in Slovenia on 11 July 2021. According to the environmental activists and the domain experts, the provisions of the law would have detrimental effects on the environment and on clean water.', 2021, 7, 11, NULL, NULL, NULL, 'day', '11 July 2021', 37, 'https://en.wikipedia.org/wiki/2021_Slovenian_Waters_Act_referendum'),
  ('Q121511279', '2023 Slovenia floods', 'In August 2023, major floods occurred in large part of Slovenia and neighbouring areas of Austria and Croatia due to heavy rain. Amongst others, the level of rivers Sava, Mur and Drava was exceptionally high.', 2023, 8, NULL, 2023, 8, 23, 'month', 'August 2023 – 23 August 2023', 43, 'https://en.wikipedia.org/wiki/2023_Slovenia_floods'),
  ('Q130297776', '2024 Central European floods', 'The 2024 Central European floods were a series of floods caused by a record heavy rainfall generated by Storm Boris, an extremely humid Genoa low. The flooding began in Austria and the Czech Republic, then spread to Poland, Romania and Slovakia, and then onwards to Germany and Hungary.', 2024, 9, NULL, NULL, NULL, NULL, 'month', 'September 2024', 57, 'https://en.wikipedia.org/wiki/2024_Central_European_floods');
